import{_ as a,c as n,o as s,ak as r}from"./chunks/framework.CtX3_w5e.js";const c=JSON.parse('{"title":"不同消息队列消息写入方式对比","description":"","frontmatter":{"sidebar":false,"pageClass":"timeline-page","title":"不同消息队列消息写入方式对比","hugoSource":"computer-science/LLM/2025-03-30-4-不同消息队列消息写入方式对比.md","outline":[1,6]},"headers":[],"relativePath":"computer-science/LLM/2026-11-17-2025-03-30-4-不同消息队列消息写入方式对比.md","filePath":"computer-science/LLM/2026-11-17-2025-03-30-4-不同消息队列消息写入方式对比.md","lastUpdated":1794887319000}'),l={name:"computer-science/LLM/2026-11-17-2025-03-30-4-不同消息队列消息写入方式对比.md"};function e(i,t,o,p,d,g){return s(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="不同消息队列消息写入方式对比" tabindex="-1">不同消息队列消息写入方式对比 <a class="header-anchor" href="#不同消息队列消息写入方式对比" aria-label="Permalink to “不同消息队列消息写入方式对比”">​</a></h1><p>以下是主流消息队列（Kafka、RocketMQ、RabbitMQ、Pulsar、ActiveMQ）在消息写入方式上的对比，结合性能、可靠性和适用场景进行综合分析：</p><hr><h3 id="_1-kafka" tabindex="-1">1. <strong>Kafka</strong> <a class="header-anchor" href="#_1-kafka" aria-label="Permalink to “1. Kafka”">​</a></h3><ul><li><strong>写入方式</strong>： <ul><li><strong>顺序追加写入</strong>：消息以追加（Append-only）方式写入分区日志文件，利用磁盘顺序I/O的高性能特性<span>1</span><span>15</span><span>28</span>。</li><li><strong>批量发送</strong>：生产者（Producer）将消息累积到批次（如1MB或100ms阈值）后批量发送，减少网络和磁盘I/O次数<span>28</span>。</li><li><strong>异步刷盘</strong>：默认异步刷盘（依赖页缓存），通过参数可配置同步刷盘（牺牲性能换可靠性）<span>28</span>。</li></ul></li><li><strong>特点</strong>： <ul><li>高吞吐（10万级/秒），适合日志、大数据场景<span>1</span><span>15</span>。</li><li>不支持延迟消息，仅保证分区内有序<span>16</span><span>28</span>。</li></ul></li></ul><hr><h3 id="_2-rocketmq" tabindex="-1">2. <strong>RocketMQ</strong> <a class="header-anchor" href="#_2-rocketmq" aria-label="Permalink to “2. RocketMQ”">​</a></h3><ul><li><strong>写入方式</strong>： <ul><li><strong>顺序写+索引</strong>：消息追加到CommitLog文件（顺序写），同时构建索引文件（ConsumeQueue）加速查询<span>42</span>。</li><li><strong>同步/异步刷盘</strong>：支持同步刷盘（强一致性）和异步刷盘（高性能）<span>42</span><span>43</span>。</li><li><strong>事务消息</strong>：通过“半消息”机制实现分布式事务，先暂存消息，本地事务提交后再确认写入<span>42</span>。</li></ul></li><li><strong>特点</strong>： <ul><li>兼顾高吞吐（10万级/秒）和功能完备性（延迟消息、事务支持）<span>16</span><span>28</span>。</li><li>适合电商、金融等业务场景<span>1</span><span>42</span>。</li></ul></li></ul><hr><h3 id="_3-rabbitmq" tabindex="-1">3. <strong>RabbitMQ</strong> <a class="header-anchor" href="#_3-rabbitmq" aria-label="Permalink to “3. RabbitMQ”">​</a></h3><ul><li><strong>写入方式</strong>： <ul><li><strong>内存+磁盘混合</strong>：默认优先写入内存，通过持久化队列（Durable Queue）将消息同步到磁盘<span>1</span><span>28</span>。</li><li><strong>Exchange路由</strong>：消息通过Exchange根据路由规则（Direct/Topic/Fanout）分发到队列<span>1</span><span>16</span>。</li></ul></li><li><strong>特点</strong>： <ul><li>实时性高（微秒级延迟），但吞吐量较低（万级/秒）<span>28</span>。</li><li>支持复杂路由和消息确认机制，适合中小规模业务<span>1</span><span>16</span>。</li></ul></li></ul><hr><h3 id="_4-pulsar" tabindex="-1">4. <strong>Pulsar</strong> <a class="header-anchor" href="#_4-pulsar" aria-label="Permalink to “4. Pulsar”">​</a></h3><ul><li><strong>写入方式</strong>： <ul><li><strong>分层存储</strong>：消息先写入Broker的内存层，再异步持久化到BookKeeper集群（计算与存储分离）<span>1</span><span>16</span>。</li><li><strong>分片（Segment）存储</strong>：Topic分区划分为Segment，分散存储提高扩展性<span>1</span>。</li></ul></li><li><strong>特点</strong>： <ul><li>支持秒级延迟消息和多租户，适合云原生和异地容灾场景<span>1</span><span>16</span>。</li><li>吞吐量接近Kafka，但架构更复杂<span>1</span>。</li></ul></li></ul><hr><h3 id="_5-activemq" tabindex="-1">5. <strong>ActiveMQ</strong> <a class="header-anchor" href="#_5-activemq" aria-label="Permalink to “5. ActiveMQ”">​</a></h3><ul><li><strong>写入方式</strong>： <ul><li><strong>内存/KahaDB/JDBC</strong>：默认KahaDB（基于日志的存储），支持JDBC持久化到数据库。</li><li><strong>同步刷盘可选</strong>：通过配置选择是否同步刷盘。</li></ul></li><li><strong>特点</strong>： <ul><li>功能全面但吞吐量最低（万级/秒），适合传统企业应用<span>28</span>。</li><li>社区活跃度低，逐渐被替代<span>28</span>。</li></ul></li></ul><hr><h3 id="对比总结" tabindex="-1"><strong>对比总结</strong> <a class="header-anchor" href="#对比总结" aria-label="Permalink to “对比总结”">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>Kafka</th><th>RocketMQ</th><th>RabbitMQ</th><th>Pulsar</th><th>ActiveMQ</th></tr></thead><tbody><tr><td><strong>写入性能</strong></td><td>最高（顺序I/O+批量）</td><td>高（顺序写+索引）</td><td>低（内存优先）</td><td>高（分层存储）</td><td>最低</td></tr><tr><td><strong>可靠性</strong></td><td>异步刷盘可能丢数据</td><td>支持同步刷盘</td><td>依赖持久化配置</td><td>高（BookKeeper）</td><td>依赖配置</td></tr><tr><td><strong>延迟消息</strong></td><td>不支持</td><td>支持</td><td>支持（插件）</td><td>支持秒级</td><td>支持</td></tr><tr><td><strong>适用场景</strong></td><td>日志/大数据</td><td>电商/金融</td><td>中小规模业务</td><td>云原生/异地容灾</td><td>传统企业应用</td></tr></tbody></table><p><strong>参考资料</strong>：<span>1</span><span>15</span><span>16</span><span>28</span><span>42</span></p>',21)])])}const u=a(l,[["render",e]]);export{c as __pageData,u as default};
